# Lesson 13 of MKTG90037: make or buy, transaction cost theory (Week 8, middle part). Brand: Coles (own fulfilment centres versus
# Uber Eats; fuel business sold to Viva with a supply arrangement; FY26). The deck's cases (Michel's, Fisher Body, 7-Eleven, Taco
# Bell, Amazon, Huawei and Leica) are the Tag items. Instruments: cost cross-over (Dial), which transaction cost (Tag).
from mk import *  # noqa: F403


def L13(CID):
    SK = 'mk.make-or-buy'
    cats = [dict(id='saf', label=T('Safeguarding', '保障成本')), dict(id='ada', label=T('Adaptation', '适应成本')), dict(id='mea', label=T('Measurement', '计量成本'))]
    items = [
        dict(text=T('Franchisees of a pastry chain had invested heavily in kitchens and layouts, and could not leave without losing it.', '一家糕点连锁的加盟商在厨房和布局上投入巨大，离开就会血本无归。'), cat='saf', why=T('A lost investment tied to one relationship: the risk of being exploited (opportunism) must be guarded against.', '投资绑死在一段关系上：必须防范被利用（机会主义）的风险。')),
        dict(text=T('A body-parts supplier had a fixed price with the car maker, and re-engineered its production to cut costs, but the buyer did not share the gain.', '一家车身零件供应商和车企签了固定价，并重新设计了生产工艺降低成本，但买方不分享收益。'), cat='ada', why=T('Conditions changed and one party could not or would not adapt the deal.', '条件变了，一方不能或不愿调整合同。')),
        dict(text=T('It is hard to check whether legal advice, software or market research was really good.', '很难核实法律意见、软件或市场研究是否真的好。'), cat='mea', why=T('Behavioural uncertainty: you cannot easily verify what you bought.', '行为的不确定性：很难核实买到了什么。')),
        dict(text=T('A franchisor opened a smaller format that competed with its own franchisees.', '特许方开了一种较小的门店形态，与自己的加盟商竞争。'), cat='saf', why=T('Opportunism: interest-seeking with guile, which safeguards must guard against.', '机会主义：狡诈地谋取私利，保障措施正是用来防它的。')),
        dict(text=T('A convenience chain has to monitor whether its franchisees underpay staff, because it harms the brand.', '一家便利店连锁必须监督加盟商是否克扣员工工资，因为这会伤害品牌。'), cat='mea', why=T('Monitoring franchisee performance is costly and underperformance hurts the franchisor.', '监督加盟商表现成本高，而表现差会伤害特许方。')),
        dict(text=T('Choosing a vendor, negotiating terms and running a tender.', '选择供应商、谈判条款、组织招标。'), cat='saf', why=T('The deck lists negotiating, selecting vendors and tendering under safeguarding.', '课件把谈判、选择供应商和招标列在保障成本下。')),
    ]
    return dict(
        id=f'{CID}-make-or-buy',
        title=T('What do I do myself and what do I buy?', '什么自己做，什么买？'),
        description=T('Transaction cost theory: the three transaction costs, the cross-over where buying stops paying, and the customer interface, with Coles.', '交易成本理论：三类交易成本、外购不再划算的交叉点，以及客户界面，案例是 Coles。'),
        minutes=45,
        skills=[{'id': SK, 'name': T('Explaining and applying transaction cost theory to make-or-buy decisions', '解释并应用交易成本理论做自制或外购决策')}],
        misconceptions=[
            {'id': 'buy-is-always-cheaper', 'description': T('buying from a specialist is always cheaper than making in-house', '向专业方购买总是比自己做便宜')},
            {'id': 'tc-is-price', 'description': T('transaction costs are just the price paid to the supplier', '交易成本就是付给供应商的价格')},
        ],
        steps=[
            read('puzzle', T('Own vans, or an app?', '自己的车，还是一个 App？'),
                 p(T("Coles delivers online orders from its own customer fulfilment centres and, in FY26, expanded its partnership with Uber Eats. It also sold its fuel stations to Viva Energy in 2023, and still buys products from Viva under a supply arrangement. In each case it chose what to **make** and what to **buy**.",
                     "Coles 用自己的客户履约中心配送线上订单，并在 2026 财年扩大了与 Uber Eats 的合作。它还在 2023 年把加油站业务卖给了 Viva Energy，并按供货协议继续从 Viva 采购产品。每一次，它都在选择什么**自己做**、什么**外购**。")),
                 p(T("Specialists are usually cheaper and better at one thing. So why does anyone make anything themselves?", "专业方通常在一件事上更便宜、更擅长。那为什么还有人什么都自己做？")), chapter=CH['puzzle']),
            predict('guess', SK, T("An outside supplier makes a part for 70; making it yourself costs 100. Is buying always better?", "外部供应商做一个零件要 70；自己做要 100。外购一定更好吗？"),
                    [(T("No: buying also brings costs of choosing, safeguarding, adapting and checking that can wipe out the 30", "不：外购还带来选择、保障、适应和核查的成本，可能把那 30 的差价吃掉"), True),
                     (T("Yes: 70 is less than 100", "是：70 比 100 小"), T("That compares production costs only. Buying adds transaction costs.", "那只比较了生产成本。外购还要加上交易成本。")),
                     (T("Yes, if the supplier is large", "是，如果供应商很大"), T("Size does not remove the costs of checking and adapting.", "规模不会消除核查和适应的成本。")),
                     (T("No: always make in-house", "不是：永远自己做"), T("Then you give up specialists’ real cost advantages.", "那就放弃了专业方真正的成本优势。"))],
                    T("**Buy: total cost = outsourcing cost + transaction costs. Make: total cost = production cost.** Move the transaction costs and watch where the better choice switches.", "**外购：总成本 = 外包成本 + 交易成本。自制：总成本 = 生产成本。** 拉动交易成本，看更好的选择在哪里换边。")),
            read('touch', T('The cross-over', '交叉点'),
                 p(T("Making costs 100. Buying costs 70 for the part, plus three transaction costs that you set. The numbers are illustrations to show the mechanism.", "自制成本是 100。外购零件是 70，再加上三项由你设置的交易成本。数字是为演示机制而设的。")),
                 dial(T('Three sliders for safeguarding, adaptation and measurement costs; the lines show total cost of making and of buying as safeguarding rises.', '三个滑块分别是保障、适应和计量成本；曲线显示随保障成本上升，自制与外购的总成本。'),
                      sliders=[dict(id='sg', label=T('Safeguarding costs', '保障成本'), min=0, max=40, step=1, value=5), dict(id='ad', label=T('Adaptation costs', '适应成本'), min=0, max=40, step=1, value=5), dict(id='me', label=T('Measurement costs', '计量成本'), min=0, max=40, step=1, value=5)],
                      consts=dict(make_cost=100, buy_part=70),
                      outs=[dict(id='make', label=T('Total cost if you make it', '自制的总成本'), expr='make_cost', dec=0, bar=dict(max=140)), dict(id='buy', label=T('Total cost if you buy it', '外购的总成本'), expr='buy_part+sg+ad+me', dec=0, bar=dict(max=140))],
                      plot=dict(x='sg', ys=[dict(out='make', label=T('make', '自制'), color='#E4572E'), dict(out='buy', label=T('buy', '外购'), color='#2563EB')], ymin=60, ymax=140, ylabel=T('total cost', '总成本'), xlabel=T('safeguarding', '保障成本')),
                      presets=[dict(label=T('A standard part, easy to check', '标准零件，容易核查'), set=dict(sg=2, ad=2, me=2)), dict(label=T('A custom part, one supplier, hard to check', '定制零件，只有一家供应商，难核查'), set=dict(sg=18, ad=14, me=12))],
                      notes=[dict(when='buy<make', text=T('**Buy**: even with transaction costs, total cost is below making it.', '**外购**：即使加上交易成本，总成本仍低于自制。')), dict(when='buy>=make', text=T('**Make**: transaction costs have eaten the supplier’s cost advantage.', '**自制**：交易成本吃掉了供应商的成本优势。')),
                             dict(when='buy_part+sg+ad+me==make_cost', text=T('Exactly at the **cross-over**.', '正好在**交叉点**上。'))],
                      caption=T("The cost of 100 and 70 are for the demonstration, not from any company.", "100 和 70 的成本是为演示而设，不来自任何公司。"), height=760),
                 chapter=CH['touch']),
            read('touch2', T('Which transaction cost is it?', '这是哪种交易成本？'),
                 p(T("Six real cases from the lecture, each showing one of the three costs.", "课程里的六个真实案例，各自体现三种成本中的一种。")),
                 tag(T('Six cases to tag as safeguarding, adaptation or measurement cost.', '六个案例，标为保障、适应或计量成本。'), cats, items,
                     done=T("**Safeguarding**: guarding against opportunism, plus negotiating and selecting. **Adaptation**: updating a deal when conditions change (co-design, innovation). **Measurement**: checking quality and tracking performance. They rise with **uncertainty** and with **investment tied to one relationship**.", "**保障**：防范机会主义，加上谈判和选择。**适应**：条件变化时调整合作（共同设计、创新）。**计量**：检查质量和追踪表现。它们随**不确定性**和**绑定在一段关系上的投资**而上升。"), height=760)),
            read('name', T('The framework, as the marker wants it', '阅卷人要的框架'),
                 p(T("The **make-or-buy decision** asks what to do yourself and what to leave to others. Others can often do it at lower cost through specialisation, routinisation and competition (Apple and Nike outsource most of their activities; Shell does most in-house). The reason not to buy everything is **transaction costs** (Coase, Nobel prize 1991), the costs of running the system. Three kinds:", "**自制或外购决策**问的是什么自己做、什么交给别人。别人往往能凭专业化、流程化和竞争做得更便宜（Apple 和 Nike 外包大部分活动；Shell 多数自己做）。不什么都买的原因是**交易成本**（Coase，1991 年诺贝尔奖），也就是运行这个系统的成本。三类：")),
                 ul(T("**Safeguarding costs**: negotiating, selecting vendors, tendering, and guarding against **opportunism** (interest-seeking with guile) when investments are tied to one relationship (a franchisee’s kitchens; switching a software system).", "**保障成本**：谈判、选择供应商、招标，以及在投资被绑定于某段关系时防范**机会主义**（狡诈地谋取私利）（加盟商的厨房；更换软件系统）。"),
                    T("**Adaptation costs**: when uncertainty changes needs and a party cannot or will not adapt, including co-design and innovation with suppliers.", "**适应成本**：不确定性改变需求，而一方不能或不愿调整，包括与供应商共同设计和创新。"),
                    T("**Measurement costs**: quality assurance, tracking and setting performance standards, when what is bought cannot easily be verified.", "**计量成本**：质量保证、追踪和设定绩效标准，当买到的东西难以核实时。")),
                 callout('note', T('The decision rule', '决策规则'), T("**Make**: total cost = production cost. **Buy**: total cost = outsourcing cost + transaction costs. Firms choose the governance with the lowest total, so for some the answer is make, for others buy; leasing or owning aircraft is the same trade-off. Then ask: **will outsourcing also give a competitive advantage in the customer’s eyes?**", "**自制**：总成本 = 生产成本。**外购**：总成本 = 外包成本 + 交易成本。企业选总成本最低的治理方式，所以对有些企业答案是自制，对另一些是外购；租还是买飞机是同样的取舍。然后再问：**外包在顾客眼里也能带来竞争优势吗？**")),
                 p(T("Link to the value chain: use transaction costs and core competences to decide which activities to outsource (Huawei uses Leica lenses to make its phones strong in photography). **The customer interface** should be outsourced only if the savings exceed the risk of losing direct contact with customers, and probably not if your discipline is customer intimacy. Amazon controls distribution, which is its operational excellence, but outsources some customer service and monitors it with surveys after each call.", "联系价值链：用交易成本和核心能力决定把哪些活动外包（华为用徕卡镜头让手机拍照出色）。**客户界面**只有在节省的成本超过失去与顾客直接联系的风险时才应外包，如果你的价值准则是客户亲密，多半不该外包。Amazon 控制配送，那是它的卓越运营；而把一部分客服外包，并用每次通话后的问卷监控它。")),
                 chapter=CH['name']),
            apply_q('apply', SK, T("Coles delivers some online orders from its own customer fulfilment centres, and some through Uber Eats (a partnership it expanded in FY26). Write four sentences: which is **make** and which **buy**, which transaction cost matters most in the buy case, and the cause and effect. Say if you are guessing.", "Coles 的一部分线上订单从自有履约中心配送，一部分通过 Uber Eats（2026 财年扩大了合作）。写四句话：哪个是**自制**、哪个是**外购**，外购情形里哪项交易成本最重要，以及因果。如果是推测，要说明。"),
                    [T("Identifies make (fulfilment centres, which were EBITDA-positive in FY26) and buy (Uber Eats)", "指出自制（履约中心，2026 财年 EBITDA 为正）和外购（Uber Eats）"), T("Names a transaction cost for the buy case (measurement of service quality, safeguarding of the customer relationship)", "为外购情形点出一项交易成本（服务质量的计量、顾客关系的保障）"),
                     T("Links to the customer interface and the risk of losing direct contact", "联系到客户界面以及失去直接联系的风险"), T("Flags what is inference", "标明哪些是推断")],
                    T("Coles makes: its own customer fulfilment centres do same-day delivery and were EBITDA-positive in FY26. It buys a part of the delivery through Uber Eats, which extends reach without building more capacity. In the buy case the costs I would expect to matter most are measurement and safeguarding: Coles must check delivery quality that is done by someone else’s drivers and protect its direct customer relationship, since the customer interface carries brand risk. This is my inference, not something Coles states. The cause and effect is that the make route gives control where service quality is the point and the buy route gives flexible reach where the transaction costs are low.",
                      "Coles 自制：自有客户履约中心做当日送达，2026 财年 EBITDA 为正。它通过 Uber Eats 外购一部分配送，在不增加更多产能的情况下扩大触达。在外购情形中，我预计最重要的是计量成本和保障成本：Coles 必须核查由别人的司机完成的配送质量，并保护自己与顾客的直接关系，因为客户界面带有品牌风险。这是我的推断，不是 Coles 的说法。因果是：自制路线在服务质量是关键的地方提供控制，外购路线在交易成本低的地方提供灵活的触达。"),
                    T("Make versus buy, then the transaction cost, then say what is inference.", "先分自制与外购，再说交易成本，再说明推断。")),
            choice('neighbour', T('The look-alike', '长得像的那个'), SK,
                   T("A firm says: “The supplier’s price is lower, so total cost is lower.” What does the answer miss?", "一家企业说：“供应商报价更低，所以总成本更低。”这个回答漏了什么？"),
                   [(T("The transaction costs of safeguarding, adaptation and measurement that come with buying", "外购带来的保障、适应和计量交易成本"), True), (T("The production cost of the supplier", "供应商的生产成本"), T("That is already in the price.", "那已经包含在价格里了。")),
                    (T("Nothing: price is total cost", "没漏什么：价格就是总成本"), T("Transaction cost theory says it is not.", "交易成本理论说不是。"))],
                   T("Total cost is production plus transaction costs when buying.", "外购时总成本是生产成本加交易成本。"), purpose='check', chapter=CH['neighbour']),
            recall('r1', SK, T("From lesson 10: a firm should make its own sales force when…", "来自第 10 课：什么时候该自建销售队伍……"),
                   [(T("selling is complex, relationships are strategic and effort is hard to monitor", "销售复杂、关系具有战略意义、努力难以监督"), True), (T("selling is standardised and cheap from specialists", "销售标准化、专业方更便宜"), T("That points to buying.", "那指向外购。"))], T("Same logic as make-or-buy.", "与自制或外购同一套逻辑。"), first=True),
            recall('r2', SK, T("From lesson 12: co-creation with suppliers has to be managed because of…", "来自第 12 课：与供应商共创需要管理，是因为……"),
                   [(T("transaction costs: safeguarding, adaptation and measurement", "交易成本：保障、适应、计量"), True), (T("only legal fees", "只有法律费用"), T("The costs are broader than legal fees.", "成本比法律费用广。"))], T("Two lessons, one logic.", "两节课，一套逻辑。")),
        ] + exam_three('exam', SK,
                       T("Question. (a) Explain transaction costs and why they matter to make-or-buy decisions. (b) Apply the three types to Coles in Australia. (c) Make two recommendations.", "题目。(a) 解释交易成本，以及它们为何影响自制或外购决策。(b) 把三类交易成本应用到澳大利亚的 Coles。(c) 给出两条建议。"),
                       (T("Write the **Explain** part.", "写**解释**部分。"),
                        [T("Transaction costs are the costs of running the system (Coase), beyond production cost", "交易成本是运行系统的成本（Coase），在生产成本之外"), T("The three types: safeguarding, adaptation, measurement", "三类：保障、适应、计量"),
                         T("Make total = production; buy total = outsourcing + transaction costs", "自制总成本 = 生产；外购总成本 = 外包 + 交易成本"), T("Firms choose the lower total, so it varies by firm and situation", "企业选总成本较低的，所以因企业和情形而异")],
                        T("Transaction costs (Coase) are the costs of running a market relationship, over and above the price paid. There are three kinds: safeguarding costs, such as negotiating, selecting vendors and guarding against opportunism; adaptation costs, when a party cannot or will not adapt to changing needs; and measurement costs, such as checking quality and tracking performance. They matter because the total cost of making is the production cost while the total cost of buying is the outsourcing cost plus the transaction costs, so firms choose whichever is lower. A specialist’s lower price does not settle the question.",
                          "交易成本（Coase）是维持一段市场关系的成本，在所付价格之外。有三类：保障成本，如谈判、选择供应商和防范机会主义；适应成本，指一方不能或不愿适应变化的需求；计量成本，如检查质量和追踪表现。它们之所以重要，是因为自制的总成本是生产成本，外购的总成本是外包成本加交易成本，所以企业选两者中较低的。专业方的低价并不能决定一切。")),
                       (T("Write the **Apply** part.", "写**应用**部分。"),
                        [T("Names real Coles make-or-buy choices: own fulfilment centres versus Uber Eats; fuel business sold to Viva with a product supply arrangement", "指出 Coles 真实的自制或外购选择：自有履约中心对 Uber Eats；加油站业务卖给 Viva，并有产品供应协议"), T("Applies each of the three costs to a case, with cause and effect", "对某个案例逐一运用三类成本，并说明因果"),
                         T("Uses true facts: fulfilment centres EBITDA-positive, the Viva arrangement worth 561 million dollars in FY26 and due to expire in November 2026", "用真实事实：履约中心 EBITDA 为正，Viva 安排在 2026 财年收入 5.61 亿澳元，2026 年 11 月到期"), T("Flags inference", "标明推断")],
                        T("Coles shows both choices. It makes online delivery through its own fulfilment centres, which were EBITDA-positive in FY26, and buys extra reach through Uber Eats. In the Viva case it sold its fuel stations in 2023 but keeps a product supply arrangement with Viva that generated 561 million dollars of revenue in FY26 and expires in November 2026. Safeguarding: because the arrangement ends, Coles must negotiate and protect its position, and its dependence on one partner is exposed to opportunism. Adaptation: a fixed arrangement is hard to change if shoppers’ needs shift. Measurement: with Uber Eats, Coles must verify delivery quality that drivers it does not employ provide. These links are my inference. The pattern is that Coles makes where control and service quality matter, and buys where reach is the aim and transaction costs are manageable.",
                          "Coles 两种选择都有。它用自有履约中心做线上配送，这些中心在 2026 财年 EBITDA 为正，并通过 Uber Eats 外购额外的触达。在 Viva 的案例中，它 2023 年卖掉了加油站，但保留与 Viva 的产品供应协议，该协议在 2026 财年带来 5.61 亿澳元收入，并将在 2026 年 11 月到期。保障成本：因为协议将到期，Coles 必须谈判并保护自己的位置，对单一伙伴的依赖容易遭遇机会主义。适应成本：一份固定的安排在购物者需求变化时很难调整。计量成本：对 Uber Eats，Coles 必须核实由并非自己雇用的司机提供的配送质量。这些联系是我的推断。规律是：Coles 在控制和服务质量重要的地方自制，在以触达为目标、交易成本可控的地方外购。")),
                       (T("Write the **Recommend** part: exactly two.", "写**建议**部分：恰好两条。"),
                        [T("Exactly two from the analysis (secure the supply arrangement; monitor outsourced delivery quality)", "恰好两条，从分析里推出（确保供应安排；监控外包配送质量）"), T("Each actionable", "每条可执行"), T("A risk named", "点出风险")],
                        T("First, start renegotiating the Viva supply arrangement well before November 2026 or line up alternative suppliers, because safeguarding costs rise as the end date nears and Coles has little leverage at the last moment. The risk is that early talks signal weakness, so run a parallel supplier search. Second, set service-level measures for Uber Eats deliveries, such as lateness and substitution rates reported back to Coles, because measurement costs fall when quality can be observed. The risk is friction with the partner, so agree the measures in the contract.",
                          "第一，在 2026 年 11 月之前很早就开始重新谈判 Viva 的供应安排，或物色替代供应商，因为随着到期日临近，保障成本上升，Coles 在最后一刻几乎没有谈判筹码。风险是过早谈判显得示弱，所以要并行寻找供应商。第二，为 Uber Eats 的配送设定服务水平指标，如迟到率和替换率并反馈给 Coles，因为质量可观察时计量成本就下降。风险是与伙伴产生摩擦，所以要在合同里约定这些指标。")),
                       ),
    )
